    if (existsSync(KEYS_FILE())) {
      const parsed = JSON.parse(readFileSync(KEYS_FILE(), 'utf-8'))
      if (parsed && typeof parsed === 'object') return parsed as KeyFile
    }
  } catch {
    // 文件损坏时按无 Key 处理，不阻塞启动
  }
  return {}
}

function saveKeys(keys: KeyFile): void {
  try {
