 * 调用前必须先通过 validateSubTasks（本函数假定无环）。
 */
export function buildDagLayers(count: number, deps: (number[] | undefined)[]): number[][] {
  const indeg = new Array<number>(count).fill(0)
  for (let i = 0; i < count; i++) indeg[i] = (deps[i] ?? []).length
