// LSP 桥接：在主进程内 spawn typescript-language-server（stdio），
// 通过 IPC 在渲染进程 Monaco 与语言服务器之间做双向 JSON-RPC 转发。
import { ipcMain } from 'electron'
import { spawn, ChildProcessWithoutNullStreams } from 'node:child_process'
import { createRequire } from 'node:module'

// 语言服务器子进程与缓冲状态
let lspProc: ChildProcessWithoutNullStreams | null = null
let lspBuffer: Buffer = Buffer.alloc(0)
let messageSender: ((msg: string) => void) | null = null

// 解析 typescript-language-server 可执行入口（本地 node_modules 内）
function resolveLsEntry(): { command: string; args: string[] } {
  const require = createRequire(__filename)
  try {
    // 优先用 node 直接跑 lib 下的 cli.mjs，避免 .cmd 包装差异
    const pkgPath = require.resolve('typescript-language-server/package.json')
    const cliPath = pkgPath.replace(/package\.json$/, 'lib/cli.mjs')
    return { command: process.execPath, args: [cliPath, '--stdio'] }
  } catch {
    // 回退：交给 npx 找
    return { command: 'npx', args: ['typescript-language-server', '--stdio'] }
  }
}

// 将一帧 LSP Content-Length 协议数据推入解析
function feedBuffer(sender: (msg: string) => void): void {
  while (true) {
    const headerEnd = lspBuffer.indexOf('\r\n\r\n')
    if (headerEnd === -1) return
    const header = lspBuffer.subarray(0, headerEnd).toString('utf-8')
    const m = /Content-Length:\s*(\d+)/i.exec(header)
    if (!m) {
      lspBuffer = lspBuffer.subarray(headerEnd + 4)
      continue
    }
    const len = parseInt(m[1], 10)
    const start = headerEnd + 4
    if (lspBuffer.length < start + len) return
    const body = lspBuffer.subarray(start, start + len).toString('utf-8')
    lspBuffer = lspBuffer.subarray(start + len)
    sender(body)
  }
}

// 包装一条 JSON-RPC 消息为 LSP 协议帧
function frame(msg: string): string {
  return `Content-Length: ${Buffer.byteLength(msg, 'utf-8')}\r\n\r\n${msg}`
}

// 注册 LSP 相关 IPC
export function registerLspHandlers(): void {
  // 启动语言服务器
  ipcMain.handle('lsp:start', async (event) => {
    if (lspProc) return { ok: true, already: true }
    const { command, args } = resolveLsEntry()
    lspProc = spawn(command, args, {
      stdio: ['pipe', 'pipe', 'pipe'],
      shell: false
    })
    lspBuffer = Buffer.alloc(0)
    messageSender = (msg: string) => {
      event.sender.send('lsp:message', msg)
    }
    lspProc.stdout.on('data', (chunk: Buffer) => {
      lspBuffer = Buffer.concat([lspBuffer, chunk])
      if (messageSender) feedBuffer(messageSender)
    })
    lspProc.stderr.on('data', (chunk: Buffer) => {
      // 语言服务器告警打印到主进程控制台，不上抛
      console.error('[lsp stderr]', chunk.toString())
    })
    lspProc.on('exit', () => {
      lspProc = null
      messageSender = null
    })
    return { ok: true }
  })

  // 渲染进程 -> 语言服务器 的单向写

