    /** 正在执行的原始命令（失败诊断用） */
    command: string
    resolve: (r: RunResult) => void
    timer: NodeJS.Timeout
    /** 已过滤哨兵的干净输出（回传给 AI） */
    chunks: string[]
  } | null = null
