    const r = appendRing({ text: 'ab', base: 0 }, 'cd', 10)
    expect(r).toEqual({ text: 'abcd', base: 0 })
  })
  it('超容量丢弃最旧内容并推进 base', () => {
    const r = appendRing({ text: 'abcdef', base: 0 }, 'gh', 5)
    expect(r.text).toBe('defgh')
